import { Injectable, computed, signal } from '@angular/core';

export interface CartItem {
  productId: string;
  name: string;
  unitPriceMinor: number;
  quantity: number;
}

@Injectable({ providedIn: 'root' })
export class CartStore {
  private readonly _items = signal<CartItem[]>([]);
  readonly items = this._items.asReadonly();
  readonly itemCount = computed(() =>
    this.items().reduce((total, item) => total + item.quantity, 0)
  );
  readonly subtotalMinor = computed(() =>
    this.items().reduce((sum, item) =>
      sum + item.unitPriceMinor * item.quantity, 0)
  );

  add(item: Omit<CartItem, 'quantity'>): void {
    this._items.update(current => {
      const exists = current.some(row => row.productId === item.productId);
      if (!exists) return [...current, { ...item, quantity: 1 }];
      return current.map(row => row.productId === item.productId
        ? { ...row, quantity: row.quantity + 1 } : row);
    });
  }

  clear(): void { this._items.set([]); }
}
// Example: inject(CartStore).add({productId:'P1',name:'Book',unitPriceMinor:1299});
// Price here is for a demonstration only; the server determines actual checkout price.

import { Component, Injectable, computed, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { BehaviorSubject } from 'rxjs';

export interface Shipment { id: string; status: 'created' | 'in-transit' | 'delivered'; }

@Injectable({ providedIn: 'root' })
export class ShipmentFeed {
  private readonly source = new BehaviorSubject<Shipment[]>([]);
  readonly shipments$ = this.source.asObservable();
  publish(items: Shipment[]): void { this.source.next(items); }
}

@Component({
  standalone: true,
  selector: 'app-shipment-view',
  template: `
    <button type="button" (click)="select('S-1')">Select S-1</button>
    <p>Selected: {{ selected()?.status ?? 'none' }}</p>
  `
})
export class ShipmentViewComponent {
  private readonly feed = inject(ShipmentFeed);
  readonly selectedId = signal<string | null>(null);
  readonly shipments = toSignal(this.feed.shipments$, { initialValue: [] as Shipment[] });
  readonly selected = computed(() =>
    this.shipments().find(item => item.id === this.selectedId()) ?? null
  );
  select(id: string): void { this.selectedId.set(id); }
}
// A real ShipmentFeed should handle auth, event ordering, reconnection and malformed data.

import { Component, computed, signal } from '@angular/core';

