import { ChangeDetectionStrategy, Component, input, signal } from '@angular/core';

export interface ProductSummary { id: string; name: string; priceMinor: number; }

@Component({
  standalone: true,
  selector: 'app-product-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <article>
      <h3>{{ product().name }}</h3>
      <p>{{ product().priceMinor / 100 }}</p>
      <button type="button" (click)="toggleDetails()">Details</button>
      @if (detailsOpen()) { <p>Product ID: {{ product().id }}</p> }
    </article>
  `
})
export class ProductCardComponent {
  readonly product = input.required<ProductSummary>();
  readonly detailsOpen = signal(false);
  toggleDetails(): void { this.detailsOpen.update(open => !open); }
}
