import { AsyncPipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, inject } from '@angular/core';
import { BehaviorSubject, catchError, map, of, startWith, switchMap } from 'rxjs';

interface Account { id: string; displayName: string; balanceMinor: number; }
type AccountView =
  | { kind: 'loading' }
  | { kind: 'success'; account: Account }
  | { kind: 'error' };

@Injectable({ providedIn: 'root' })
export class AccountApi {
  private readonly http = inject(HttpClient);
  get(id: string) {
    return this.http.get<Account>(`/api/accounts/${encodeURIComponent(id)}`);
  }
}

@Component({
  standalone: true,
  selector: 'app-account-switcher',
  imports: [AsyncPipe],
  template: `
    <button type="button" (click)="select('A')">Account A</button>
    <button type="button" (click)="select('B')">Account B</button>
    @if (view$ | async; as view) {
      @switch (view.kind) {
        @case ('loading') { <p role="status">Loading account...</p> }
        @case ('error') { <p role="alert">Could not load account.</p> }
        @case ('success') {
          <p>{{ view.account.displayName }}: {{ view.account.balanceMinor }}</p>
        }
      }
    }
  `
})
export class AccountSwitcherComponent {
  private readonly api = inject(AccountApi);
  private readonly selectedId = new BehaviorSubject<string>('A');
  readonly view$ = this.selectedId.pipe(
    switchMap(id => this.api.get(id).pipe(
      map((account): AccountView => ({ kind: 'success', account })),
      startWith({ kind: 'loading' } as AccountView),
      catchError(() => of({ kind: 'error' } as AccountView))
    ))
  );
  select(id: string): void { this.selectedId.next(id); }
}
// Backend must authorize access for the authenticated account owner.
